UPDATE `quest_template_locale` SET `Details` = '' WHERE (`ID`, `locale`) IN ((8576, 'frFR')) AND BINARY `Details` = BINARY 'Commençons par le commencement ! Il faut comprendre ce que Azuregos a écrit dans ce registre. Vous dites qu\'il vous a demandé de fabriquer une bouée en arcanite avec le schéma ? Étrange qu\'il ait écrit ça en draconique. Ce vieux bouc sait que je ne peux pas déchiffrer ces absurdités. Pour que ça marche, il me faut mes lunettes de divination, un poulet de deux cents kilos et le tome II de Draconique pour les Nuls.';
UPDATE `quest_template_locale` SET `Details` = '' WHERE (`ID`, `locale`) IN ((8555, 'frFR')) AND BINARY `Details` = BINARY 'Eranikus, Vaelastrasz, et Azuregos... Vous avez certainement entendu parler de ces dragons, mortel. Ce n\'est pas une simple coïncidence si chacun d\'eux a joué un grand rôle comme gardien de ce monde. Malheureusement, et ma propre naïveté en est en partie responsable, ces gardiens ont tous succombé à de terribles tragédies, si terribles qu\'elles ont alimenté ma méfiance à l\'égard de votre espèce. Cherchez-les… Et préparez-vous au pire.';
UPDATE `quest_template_locale` SET `Details` = 'He, $R, seid Ihr an Schätzen interessiert? Wusste ich es doch, dass das Eure Aufmerksamkeit gewinnen würde.$B$BHier an den Flussdocks geht das Gerücht um, dass einer der Minenarbeiter in der Felsadermine der Venture Company nordöstlich von hier einen Smaragd von der Größe Eurer Faust gefunden hat.$B$BIch kenne ein paar Käufer, die daran interessiert wären, so etwas in die Finger zu bekommen, und ich wäre bereit, halbe-halbe beim Verkauf mit Euch zu machen. Seid Ihr dabei?' WHERE (`ID`, `locale`) IN ((896, 'deDE')) AND BINARY `Details` = BINARY 'Als Werftmeister eines so geschäftigen Hafens wie Ratchet habe ich mein Ohr immer am Puls der Zeit. Ich weiß alles über den Verkehr von Waren und Geld zwischen hier und Booty Bay. Die jüngste Neuigkeit, die ich erfahren habe, betrifft die Felsadermine der Venture Company nordöstlich des Schlickermoores. Einer der Minenarbeiter hat dort einen faustgroßen Smaragd gefunden. Ich kenne ein paar Käufer, die sich die Finger nach so etwas ablecken würden... und ich würde bei einem Verkauf Halbe-Halbe machen.';
UPDATE `quest_template_locale` SET `Details` = 'Hé, $r, ça vous intéresse, les pierres précieuses ? Je savais que ça piquerait votre curiosité.$b$bÀ ce qu’on dit sur les docks de la rivière, l’un des mineurs de la KapitalRisk qui exploite la mine des Pierriers juste au nord-est a trouvé une émeraude de la taille de votre poing.$b$bJe connais quelques acheteurs qui seraient intéressés par un tel caillou, et je suis prêt à faire cinquante-cinquante sur sa vente. Ça vous tente ?' WHERE (`ID`, `locale`) IN ((896, 'frFR')) AND BINARY `Details` = BINARY 'Etant Maître des quais d\'un port plein d\'activité comme Ratchet, je prends toujours le pouls de l\'information. Je sais tout des échanges de biens et d\'argent entre ici et Baie-du-Butin. La dernière nouvelle que j\'ai entendue concerne la mine des Pierriers de la KapitalRisk, au nord-est de la Videfange. L\'un des mineurs y a découvert une émeraude aussi grosse que votre poing. Je connais quelques acheteurs qui voudraient mettre la main sur un tel joyau, et je suis prêt à faire 50-50.';
UPDATE `quest_template_locale` SET `Details` = 'L\'illusion et le déguisement. C\'est grâce à eux que vous pourrez tromper le Vol noir et obtenir ce que vous désirez.$B$BMême si j\'aurais quelques tours à vous apprendre dans l\'art de la dissimulation, c\'est un maître du genre qu\'il vous faut.$B$BJe connais une personne qui serait parfaite pour ça. Dans les Maleterres de l\'Ouest, vous trouverez Myranda la Mégère, qui fut autrefois une maîtresse illusionniste de Lordaeron. Elle a aidé les nôtres dans le passé, et si elle juge que votre cause en est digne, elle vous aidera peut-être également.$B$BApportez-lui ce message.' WHERE (`ID`, `locale`) IN ((6568, 'frFR')) AND BINARY `Details` = BINARY 'Que connaissez-vous des illusions? Parce que c\'est une illusion que vous devez créer pour circonvenir les défenses du Vol noir. Je connais une personne qui acceptera de vous aider dans votre recherche de l\'art de la tromperie. Elle a aidé les nôtres dans le passé, quand elle jugeait que la cause en était digne. Dans les Maleterres de l\'ouest, vous trouverez Myranda la Sorcière, un Maître Illusionniste, exilée de l\'Alliance de Lordaeron. Allez là-bas et prenez avec vous ce message.';
UPDATE `quest_template_locale` SET `Details` = 'Oye, $r, ¿te interesaría algún tesoro? Sabía que eso llamaría tu atención.$b$bPor el muelle del río se dice que uno de los mineros de Mina Pedrusco de Ventura y Cía. al noreste de aquí descubrió una esmeralda del tamaño de tu puño.$b$BSé de unos cuantos compradores que estarían interesados en ponerle las manos encima y no me importaría ir a medias en la venta. ¿Qué dices?' WHERE (`ID`, `locale`) IN ((896, 'esES'), (896, 'esMX')) AND BINARY `Details` = BINARY 'Como maestro de los muelles de un puerto tan activo como Trinquete, estoy al tanto de cualquier información. Lo sé todo del intercambio de mercancía y dinero entre este lugar y Bahía del Botín. Lo último que he oído es sobre Mina Pedrusco de Ventura y Cía. al noreste de El Fangal. Uno de los mineros descubrió una esmeralda del tamaño de tu puño. Sé de unos cuantos compradores que estarían interesados en ponerle las manos encima y no me importaría ir a medias en la venta.';
UPDATE `quest_template_locale` SET `Details` = 'Que diriez-vous de rendre une petite visite au général ? Mais sans illusion, cette fois.$B$BUne cérémonie, hein ? Ce n\'est qu\'un joli mot pour décrire le genre de sauvagerie sanglante qui amuse le Vol noir.$B$BL\'amulette n\'a besoin que d\'être baignée dans le sang du général Drakkisath. C\'est une mesure de sécurité primitive. Et il y a d\'autres moyens de se procurer le sang du général...$B$BRetournez au pic Rochenoire et détruisez Drakkisath. Rapportez son sang ici et j\'activerai la clé du repaire d\'Onyxia.' WHERE (`ID`, `locale`) IN ((6602, 'frFR')) AND BINARY `Details` = BINARY 'Vous irez rendre visite au général, mais pas en tant que dragon noir. Vous voyez, une cérémonie n\'est qu\'un autre terme pour permettre de verser du sang au Vol noir. L\'amulette inachevée a simplement besoin du sang du général pour s\'activer. Un de leurs mécanismes à sûreté intégrée. Retournez au pic Blackrock et détruisez Drakkisath. Rapportez son sang ici et j\'activerai la clé du repaire d\'Onyxia.';
UPDATE `quest_template_locale` SET `Details` = 'Rexxar, l\'un de mes champions les plus loyaux, a trouvé un chemin pour pénétrer dans la tanière du dragon. Il a cependant quitté Azeroth pour se joindre à notre expédition en Outreterre.$B$BIl a laissé l\'information à son compagnon, Rokaro, au village Proie-de-l\'ombre. Vous devez aller le trouver.' WHERE (`ID`, `locale`) IN ((6567, 'frFR')) AND BINARY `Details` = BINARY 'L\'un de mes champions m\'a envoyé un mot pour dire qu\'il existait peut-être un chemin dans la tanière du dragon. Vous devez le rejoindre. Rexxar se trouve sur la terre déserte de Désolace, entre les Serres-Rocheuses et Feralas. Il attend votre venue.';
UPDATE `quest_template_locale` SET `Details` = 'Un médaillon a été façonné à partir des crânes de nos ennemis. Vous connaissez ce médaillon, n\'est-ce pas ? Vous l\'avez sûrement vu porté par vos aînés.$B$BPrenez cela. Retournez au Pic et présentez-le au général Drakkisath. Il y placera l\'enchantement final pour mettre ce bibelot en phase avec votre esprit.$B$BVous porterez ce médaillon avec honneur, en signe de votre accession à l\'un de nos rangs les plus fermés : Gardien de la mère des couvées.$B$BAllez !' WHERE (`ID`, `locale`) IN ((6601, 'frFR')) AND BINARY `Details` = BINARY 'Un médaillon a été façonné à partir des crânes de nos ennemis. Vous connaissez ce médaillon, n\'est-ce pas ? Vous l\'avez sûrement vu porté par vos aînés. Prenez cela. Retournez au Pic et présentez-le au général Drakkisath. Il y placera l\'enchantement final pour mettre ce bibelot en phase avec votre esprit. Vous porterez ce médaillon avec honneur, en signe de votre accession à l\'un de nos rangs les plus fermés : Gardien de la mère des couvées. Allez !';
