UPDATE `quest_template_locale` SET `Objectives` = 'Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Rochenoire. Peut-être devriez-vous trouver Rokaro et lui exposer votre fâcheuse situation. Montrez-lui l\'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.' WHERE (`ID`, `locale`) IN ((6601, 'frFR')) AND BINARY `Objectives` = BINARY 'Il semble que la comédie soit finie. Vous savez que l\'Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l\'intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l\'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.';
